import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(new BufferedReader(new InputStreamReader(System.in)).readLine().trim());

        if (n == 2) {
            System.out.println(-1);
            return;
        }

        StringBuilder out = new StringBuilder();

        if ((n & 1) == 1) {
            int value = 1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (j > 0) out.append(' ');
                    out.append(value++);
                }
                out.append('\n');
            }
        } else {
            int[] values = new int[n];
            for (int i = 0; i < n - 1; i++) values[i] = i;
            values[n - 1] = (n - 2) * (n + 1) / 2;

            int maxValue = values[n - 1];
            int scale = maxValue + 1;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (j > 0) out.append(' ');
                    out.append(1 + scale * values[i] + values[j]);
                }
                out.append('\n');
            }
        }

        System.out.print(out);
    }
}
